INSERT INTO produto (id, categoria_id, nome, plataforma, desenvolvedora, distribuidora, midia, preco, desconto, estoque, imagem, classificacao, data_lancamento, descricao, quantidade_avaliacoes, avaliacao_nota_um, avaliacao_nota_dois, avaliacao_nota_tres, avaliacao_nota_quatro, avaliacao_nota_cinco) VALUES (28, 1, 'Final Fantasy VII', 'PLAYSTATION_1', 'Square', 'Square', 'FISICA', 189.90, 0.00, 1, 'https://lojavirtualcdist.vercel.app/Final%20Fantasy%20VII.webp', 'DOZE', '1997-01-31', 'Final Fantasy VII acompanha o mercenário Cloud Strife e o grupo AVALANCHE na luta contra a corporação Shinra e contra Sephiroth. Edição original em três discos para o primeiro PlayStation.', 66, 2, 8, 14, 23, 19);
INSERT INTO produto (id, categoria_id, nome, plataforma, desenvolvedora, distribuidora, midia, preco, desconto, estoque, imagem, classificacao, data_lancamento, descricao, quantidade_avaliacoes, avaliacao_nota_um, avaliacao_nota_dois, avaliacao_nota_tres, avaliacao_nota_quatro, avaliacao_nota_cinco) VALUES (29, 3, 'GoldenEye 007', 'NINTENDO_64', 'Rare', 'Nintendo', 'FISICA', 159.90, 0.20, 1, 'https://lojavirtualcdist.vercel.app/GoldenEye%20007.webp', 'DEZESSEIS', '1997-08-25', 'GoldenEye 007 adapta o filme de James Bond e redefiniu o tiro em primeira pessoa nos consoles, com missões de infiltração, objetivos por dificuldade e o lendário multiplayer em tela dividida para quatro jogadores.', 75, 2, 7, 6, 20, 40);
INSERT INTO produto (id, categoria_id, nome, plataforma, desenvolvedora, distribuidora, midia, preco, desconto, estoque, imagem, classificacao, data_lancamento, descricao, quantidade_avaliacoes, avaliacao_nota_um, avaliacao_nota_dois, avaliacao_nota_tres, avaliacao_nota_quatro, avaliacao_nota_cinco) VALUES (30, 1, 'Castlevania: Symphony of the Night', 'PLAYSTATION_1', 'Konami Computer Entertainment Tokyo', 'Konami', 'FISICA', 219.90, 0.00, 1, 'https://lojavirtualcdist.vercel.app/Castlevania%20Symphony%20of%20the%20Night.webp', 'DOZE', '1997-03-20', 'Castlevania: Symphony of the Night coloca Alucard para explorar o castelo de Drácula em um mapa livre repleto de segredos, itens e evolução de personagem. É o título que batizou o gênero metroidvania.', 64, 2, 8, 9, 10, 35);